/*
 * [bud].[jsAutoApproveBudgetAfter48Hours] — LIVE definition, supplied 2026-09-24.
 * Created 2025-11-13 12:05:08.777 · Modified 2026-06-27 11:52:53.663
 * Source: sys.sql_modules.definition, copied from an SSMS results grid.
 *
 * The grid collapsed every line break into spaces, so the definition below is
 * the original text on ONE line, otherwise verbatim. Read it; do not run it —
 * the first `--` comment would comment out everything after it. For a runnable
 * copy use SSMS Tasks > Generate Scripts.
 *
 * Run by SQL Agent job "48 hrs" (enabled) every 10 minutes as
 *     exec [bud].[jsAutoApproveBudgetAfter48Hours] 75
 * Not in JSAPNEW source; JSAP C# never calls it.
 *
 * jsUser, checked 2026-09-24: 75 = Gagandeep Singh (a named user account, not a
 * dedicated system account). Never auto-approved on behalf of: 68 Nirmal Kaur,
 * 79 Gurpreet Singh, 95 Arshdeep Singh.
 *
 * bud.jsAutoApprovalLog row counts by actionType, 2026-09-24:
 *   SKIPPED_LIMIT 6,389,292 · SKIPPED_BAD_MONTH 297,702 · AUTO_APPROVE 271,185
 *   SKIPPED 100,285 · SKIPPED_NO_BUDGET 64,258 · FINAL_APPROVE 1,920
 *   MOVE_STAGE 71 · ERROR 13
 * (Rows, not documents: a skipped document is logged again every 10 minutes,
 * and AUTO_APPROVE is logged even when approvalsAdded = 0.)
 *
 * Distinct documents per actionType (same date), with SUM(approvalsAdded):
 *   AUTO_APPROVE 2,335 docs / 1,991 approvals inserted · FINAL_APPROVE 1,920
 *   MOVE_STAGE 66 · SKIPPED_LIMIT 2,652 · SKIPPED_BAD_MONTH 411 · SKIPPED 51
 *   SKIPPED_NO_BUDGET 2 · ERROR 5
 * (A document can appear under several actionTypes over its life.)
 */
  CREATE PROCEDURE [bud].[jsAutoApproveBudgetAfter48Hours]      @systemUserId INT = 75  AS  BEGIN      SET NOCOUNT ON;        DECLARE          @docId              INT,          @currentStageId     INT,          @templateId         INT,          @currentStage       INT,          @approvalRequired   INT,          @approvedCount      INT,          @hoursInStage       DECIMAL(10,2),          @lastActionDate     DATETIME,          @stageEntryDate     DATETIME,          @docCompany         INT,          @docCompanyStr      VARCHAR(50),   -- original string for joins            /* ===== BUDGET VALIDATION VARIABLES ===== */          @currentMonth       VARCHAR(20),          @budgetType         VARCHAR(50),          @currentDocAmount   DECIMAL(18,2),          @monthlyUsed        DECIMAL(18,2),          @monthlyAllocated   DECIMAL(18,2),          @currentMonthDate   DATE;        BEGIN TRY            DECLARE budget_cursor CURSOR LOCAL FAST_FORWARD FOR          SELECT              id,              currentStageId,              templateId,              currentSatge,              updatedOn          FROM bud.jsDocEntry          WHERE status = 'P'            AND currentStageId IS NOT NULL;            OPEN budget_cursor;            FETCH NEXT FROM budget_cursor INTO              @docId, @currentStageId, @templateId,              @currentStage, @stageEntryDate;            WHILE @@FETCH_STATUS = 0          BEGIN                -- Reset per-iteration variables              SET @docCompany       = NULL;              SET @docCompanyStr    = NULL;              SET @currentMonth     = NULL;              SET @budgetType       = NULL;              SET @currentDocAmount = NULL;              SET @monthlyUsed      = NULL;              SET @monthlyAllocated = NULL;              SET @currentMonthDate = NULL;                /* =================================================                 Derive Company from jsDocEnrtyDetail                 ================================================= */              SELECT TOP 1                  @docCompanyStr = company,                  @docCompany =                      CASE                           WHEN company = 'OIL'      THEN 1                          WHEN company = 'BEVERAGE'  THEN 2                          ELSE 3                      END              FROM bud.jsDocEnrtyDetail              WHERE docId = @docId              ORDER BY visOrder;                IF @docCompany IS NULL              BEGIN                  INSERT INTO bud.jsAutoApprovalLog                  (docId, company, actionType, performedBy, remarks)                  VALUES                  (@docId, 0, 'SKIPPED', @systemUserId,                   'Company not found in jsDocEnrtyDetail');                    FETCH NEXT FROM budget_cursor INTO                      @docId, @currentStageId, @templateId,                      @currentStage, @stageEntryDate;                  CONTINUE;              END                /* =================================================                 Calculate inactivity hours                 ================================================= */              SELECT @lastActionDate = MAX(createdOn)              FROM bud.jsBudgetStatusWorkflow              WHERE docId = @docId                AND stageId = @currentStageId;                SET @hoursInStage =                  DATEDIFF(HOUR,                      ISNULL(@lastActionDate, @stageEntryDate),                      GETDATE());                IF @hoursInStage >= 48              BEGIN                    /* =================================================                     ⭐ BUDGET VALIDATION — check monthly allocation                     ================================================= */                    -- 1) Current document's amount, month & budget type                  --    TOP 1 guards against multiple rows                  SELECT TOP 1                      @currentMonth    = bt.CURRENTMONTH,                      @budgetType      = bt.BUDGET,                      @currentDocAmount = t.totalAmt                  FROM (                      SELECT                          bt2.CURRENTMONTH,                          bt2.BUDGET,                          SUM(bt2.amount) AS totalAmt                      FROM bud.jsDocEntry d                      JOIN bud.jsDocEnrtyDetail dd                          ON d.id = dd.docId                      JOIN bud.jsBudgetTable bt2                          ON bt2.docentry = d.docentry                          AND bt2.Branch   = dd.company                          AND bt2.LineNum  = dd.lineNum                          AND bt2.VisOrder = dd.visOrder                          AND bt2.ObjType  = dd.objType                      WHERE d.id = @docId                      GROUP BY bt2.CURRENTMONTH, bt2.BUDGET                  ) t                  JOIN bud.jsBudgetTable bt                      ON bt.CURRENTMONTH = t.CURRENTMONTH                      AND bt.BUDGET      = t.BUDGET                  WHERE 1=1;   -- placeholder; TOP 1 handles safety                    -- Skip if we couldn't determine budget info                  IF @currentMonth IS NULL OR @budgetType IS NULL                  BEGIN                      INSERT INTO bud.jsAutoApprovalLog                      (docId, company, actionType, performedBy, remarks)                      VALUES                      (@docId, @docCompany, 'SKIPPED_NO_BUDGET', @systemUserId,                       'Could not determine CURRENTMONTH / BUDGET from jsBudgetTable');                        FETCH NEXT FROM budget_cursor INTO                          @docId, @currentStageId, @templateId,                          @currentStage, @stageEntryDate;                      CONTINUE;                  END                    -- Simplify: re-derive amount cleanly                  SELECT @currentDocAmount = SUM(bt.amount)                  FROM bud.jsDocEntry d                  JOIN bud.jsDocEnrtyDetail dd                      ON d.id = dd.docId                  JOIN bud.jsBudgetTable bt                      ON bt.docentry = d.docentry                      AND bt.Branch   = dd.company                      AND bt.LineNum  = dd.lineNum                      AND bt.VisOrder = dd.visOrder                      AND bt.ObjType  = dd.objType                  WHERE d.id = @docId                    AND bt.CURRENTMONTH = @currentMonth                    AND bt.BUDGET       = @budgetType;                      -- 2) Monthly used: sum of approved docs for same company/month/budget                  --    Uses @docCompanyStr (VARCHAR) to match dd.company correctly                  SELECT @monthlyUsed = ISNULL(SUM(bt.amount), 0)                  FROM bud.jsDocEntry d                  JOIN bud.jsDocEnrtyDetail dd                      ON d.id = dd.docId                  JOIN bud.jsBudgetTable bt                      ON bt.docentry = d.docentry                      AND bt.Branch   = dd.company                      AND bt.LineNum  = dd.lineNum                      AND bt.VisOrder = dd.visOrder                      AND bt.ObjType  = dd.objType                  WHERE dd.company        = @docCompanyStr      -- ← string match, not INT                    AND bt.CURRENTMONTH   = @currentMonth                    AND bt.BUDGET         = @budgetType                    AND d.id             <> @docId              -- exclude current doc                    AND d.status          = 'A'                 -- fully approved docs                  ;                      -- 3) Convert month string → DATE                  --    Handles MM/YYYY, MMYYYY, YYYY-MM gracefully                  BEGIN TRY                        IF CHARINDEX('/', @currentMonth) > 0                          -- MM/YYYY                          SET @currentMonthDate = DATEFROMPARTS(                              CAST(PARSENAME(REPLACE(@currentMonth,'/','.'),1) AS INT),                              CAST(PARSENAME(REPLACE(@currentMonth,'/','.'),2) AS INT),                              1                          );                                        ELSE IF CHARINDEX('-', @currentMonth) > 0                      BEGIN                          -- Detect if format is MM-YYYY                          IF LEN(@currentMonth) = 7 AND LEFT(@currentMonth,2) BETWEEN '01' AND '12'                              SET @currentMonthDate = DATEFROMPARTS(                                  CAST(RIGHT(@currentMonth,4) AS INT),                                  CAST(LEFT(@currentMonth,2) AS INT),                                  1                              );                                            -- Format YYYY-MM                          ELSE                              SET @currentMonthDate = DATEFROMPARTS(                                  CAST(LEFT(@currentMonth,4) AS INT),                                  CAST(RIGHT(@currentMonth,2) AS INT),                                  1                              );                      END                                        ELSE IF LEN(@currentMonth) = 6                          -- MMYYYY                          SET @currentMonthDate = DATEFROMPARTS(                              CAST(RIGHT(@currentMonth,4) AS INT),                              CAST(LEFT(@currentMonth,2) AS INT),                              1                          );                                        ELSE                          SET @currentMonthDate = NULL;                                    END TRY                  BEGIN CATCH                      SET @currentMonthDate = NULL;                  END CATCH                    IF @currentMonthDate IS NULL                  BEGIN                      INSERT INTO bud.jsAutoApprovalLog                      (docId, company, actionType, performedBy, remarks)                      VALUES                      (@docId, @docCompany, 'SKIPPED_BAD_MONTH', @systemUserId,                       'Could not parse CURRENTMONTH: ' + ISNULL(@currentMonth,'NULL'));                        FETCH NEXT FROM budget_cursor INTO                          @docId, @currentStageId, @templateId,                          @currentStage, @stageEntryDate;                      CONTINUE;                  END                      -- 4) Get monthly allocation                  SELECT @monthlyAllocated = bm.allocatedAmount                  FROM bud.BudgetMonthlyAllocations bm                  JOIN bud.budgets b                      ON b.budgetid = bm.budgetId                  WHERE b.company         = @docCompany                    AND bm.allocationMonth = @currentMonthDate                    AND b.budgetName       = @budgetType;                      -- 5) Guard: skip if allocation would be exceeded                  IF (@monthlyUsed + ISNULL(@currentDocAmount,0)) > ISNULL(@monthlyAllocated, 0)                  BEGIN                      INSERT INTO bud.jsAutoApprovalLog                      (docId, company, actionType, performedBy, remarks)                      VALUES                      (@docId, @docCompany, 'SKIPPED_LIMIT', @systemUserId,                       'Monthly allocation exceeded. Used='                       + CAST(@monthlyUsed AS VARCHAR)                       + ' + DocAmt='                       + CAST(ISNULL(@currentDocAmount,0) AS VARCHAR)                       + ' > Allocated='                       + CAST(ISNULL(@monthlyAllocated,0) AS VARCHAR));                        FETCH NEXT FROM budget_cursor INTO                          @docId, @currentStageId, @templateId,                          @currentStage, @stageEntryDate;                      CONTINUE;                  END                    /* ===== END BUDGET VALIDATION ===== */                      /* =================================================                     Original approval logic (unchanged)                     ================================================= */                  SELECT @approvalRequired = jac.approval                  FROM jsStage js                  INNER JOIN jsApprovalCount jac                      ON js.approvalId = jac.id                  WHERE js.id = @currentStageId;                    SELECT @approvedCount = COUNT(*)                  FROM bud.jsBudgetStatusWorkflow                  WHERE docId   = @docId                    AND stageId = @currentStageId                    AND status  = 'A';                    IF @approvedCount < @approvalRequired                  BEGIN                      BEGIN TRANSACTION;                        DECLARE                          @userId INT,                          @autoApprovalCount INT = 0;                        DECLARE user_cursor CURSOR LOCAL FAST_FORWARD FOR                      SELECT TOP (@approvalRequired - @approvedCount)                          us.userId                      FROM jsUserStage us                      WHERE us.stageId = @currentStageId                        AND us.userId NOT IN (68, 79, 95)                        AND NOT EXISTS (                            SELECT 1                            FROM bud.jsBudgetStatusWorkflow b                            WHERE b.docId   = @docId                              AND b.stageId = @currentStageId                              AND b.userId  = us.userId                              AND b.status  = 'A'                        );                        OPEN user_cursor;                      FETCH NEXT FROM user_cursor INTO @userId;                        WHILE @@FETCH_STATUS = 0                      BEGIN                          INSERT INTO bud.jsBudgetStatusWorkflow                          (docId, status, stageId, templateId,                           userId, createdOn, description)                          VALUES                          (@docId, 'A', @currentStageId,                           @templateId, @userId,                           GETDATE(),                           'Auto-approved after 48 hours');                            SET @autoApprovalCount += 1;                          FETCH NEXT FROM user_cursor INTO @userId;                      END                        CLOSE user_cursor;                      DEALLOCATE user_cursor;                        INSERT INTO bud.jsAutoApprovalLog                      (docId, company, stageId, stageNo,                       actionType, approvalsAdded,                       hoursInStage, performedBy, remarks)                      VALUES                      (@docId, @docCompany, @currentStageId,                       @currentStage, 'AUTO_APPROVE',                       @autoApprovalCount,                       @hoursInStage, @systemUserId,                       'Auto approvals inserted');                        SELECT @approvedCount = COUNT(*)                      FROM bud.jsBudgetStatusWorkflow                      WHERE docId   = @docId                        AND stageId = @currentStageId                        AND status  = 'A';                        DECLARE @totalStages INT;                      SELECT @totalStages = totalStage                      FROM bud.jsDocEntry                      WHERE id = @docId;                        /* ===== FINAL vs MOVE ===== */                      IF @approvedCount >= @approvalRequired                      BEGIN                          IF @currentStage = @totalStages                          BEGIN                              UPDATE bud.jsDocEntry                              SET status = 'A'                              WHERE id = @docId;                                EXEC bud.jsSyncBudgetToHanaDraftApproval                                  @docId, @docCompany,                                  'A', @systemUserId,                                  'Final auto-approval';                                INSERT INTO bud.jsAutoApprovalLog                              (docId, company, stageId, stageNo,                               actionType, statusSent,                               hoursInStage, performedBy, remarks)                              VALUES                              (@docId, @docCompany,                               @currentStageId, @currentStage,                               'FINAL_APPROVE', 'A',                               @hoursInStage, @systemUserId,                               'Final stage auto-approved');                          END                          ELSE                          BEGIN                              DECLARE                                  @nextStage INT = @currentStage + 1,                                  @nextStageId INT;                                SELECT @nextStageId = stageId                              FROM jsStageTemplate                              WHERE templateId = @templateId                                AND priority   = @nextStage;                                UPDATE bud.jsDocEntry                              SET currentSatge   = @nextStage,                                  currentStageId = @nextStageId,                                  updatedOn      = GETDATE()                              WHERE id = @docId;                                EXEC bud.jsSyncBudgetToHanaDraftApproval                                  @docId, @docCompany,                                  'V', @systemUserId,                                  'Moved to next stage';                                INSERT INTO bud.jsAutoApprovalLog                              (docId, company, stageId, stageNo,                               actionType, statusSent,                               hoursInStage, performedBy, remarks)                              VALUES                              (@docId, @docCompany,                               @currentStageId, @currentStage,                               'MOVE_STAGE', 'V',                               @hoursInStage, @systemUserId,                               'Moved to next stage');                          END                      END                        COMMIT TRANSACTION;                  END              END                FETCH NEXT FROM budget_cursor INTO                  @docId, @currentStageId, @templateId,                  @currentStage, @stageEntryDate;          END            CLOSE budget_cursor;          DEALLOCATE budget_cursor;        END TRY      BEGIN CATCH          IF @@TRANCOUNT > 0 ROLLBACK;            -- Close cursors if still open          IF CURSOR_STATUS('local', 'user_cursor') >= 0          BEGIN              CLOSE user_cursor;              DEALLOCATE user_cursor;          END            IF CURSOR_STATUS('local', 'budget_cursor') >= 0          BEGIN              CLOSE budget_cursor;              DEALLOCATE budget_cursor;          END            INSERT INTO bud.jsAutoApprovalLog          (docId, company, actionType, performedBy, remarks)          VALUES          (ISNULL(@docId, 0), ISNULL(@docCompany, 0),           'ERROR', @systemUserId, ERROR_MESSAGE());            THROW;      END CATCH  END
